#define cmul(A,B) ( mat2( A, -(A).y, (A).x ) * (B) )  // by deMoivre formula


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    // thanks for @FabriceNeyret2's advice
    vec2 uv = fragCoord/iResolution.y-vec2(1./3.,0.);

    // Scale and center the coordinates
    vec2 z = 3.*uv-1.5; // map(uv.x, 0, 1, -2, 2), map(uv.y, 0, 1, -2, 2)

    float q0 = 0.085;
    vec2 first = vec2(0.0);

    //getLastColor equivalent (inline for simplicity)
    float s = q0;
    vec2 c = vec2(0.3, 0.5);
    for (int index = 0; index < 40; index++) {
        vec2 newz = c + cmul(z, z);
        if ( newz == z || length(newz) > 2.0) {
            break;
        }
        z = newz;
        s = min(s, distance(z, first));
    }

    //Color mapping
    vec3 col = vec3(0.0);
    if (s < q0) {
        col = vec3(1.0 - clamp(s, 0.0, 1.0)); // map(s, 0, 1, 0, 1) and then 1 - x, also clamp to [0,1]
    }

    fragColor = vec4(col,1.0);
}
